INSERT INTO positions (election_id,title,max_votes,sort_order) SELECT e.id,t.t,1,t.o FROM elections e CROSS JOIN (SELECT 'President' t, 0 o UNION ALL SELECT 'Vice-President' t, 1 o UNION ALL SELECT 'Secretary' t, 2 o UNION ALL SELECT 'Treasurer' t, 3 o UNION ALL SELECT 'Auditor' t, 4 o UNION ALL SELECT 'Public Information Officer' t, 5 o UNION ALL SELECT 'Peace Officer' t, 6 o) t WHERE e.description LIKE 'LOADTEST%';
INSERT INTO party_lists (election_id,name,platform,color) SELECT e.id,t.n,t.p,t.c FROM elections e CROSS JOIN (SELECT 'Tugon Party' n, 'Serbisyong may puso: mas mabilis na aksyon sa hinaing ng estudyante.' p, '#6B1A2A' c UNION ALL SELECT 'Alab Kabataan' n, 'Aktibong student voice sa lahat ng usapin ng kolehiyo.' p, '#D97706' c UNION ALL SELECT 'Liwanag Alliance' n, 'Transparent na pondo at bukas na liderato.' p, '#2563EB' c UNION ALL SELECT 'Bayanihan Bloc' n, 'Sama-samang proyekto para sa bawat kurso.' p, '#059669' c UNION ALL SELECT 'Sulong GNC' n, 'Modernong campus, mas maayos na serbisyo.' p, '#7C3AED' c UNION ALL SELECT 'Tanglaw Coalition' n, 'Edukasyong abot-kaya at patas para sa lahat.' p, '#DB2777' c UNION ALL SELECT 'Diwa ng Bayan' n, 'Pagpapahalaga sa kultura, sining at palakasan.' p, '#0891B2' c UNION ALL SELECT 'Pag-asa Movement' n, 'Suporta sa mga scholar at working students.' p, '#65A30D' c) t WHERE e.description LIKE 'LOADTEST%';
