-- ============================================================================
-- GNC-OSA PORTAL - TEST DATA ONLY (walang schema / walang system data)
-- I-import MUNA ang gnc_osa_portal.sql sa database na gnc_osa_portal,
-- TAPOS i-import ang file na ito sa PAREHONG database.
-- Pambura: 9_cleanup_remove_test_data.sql
-- ============================================================================
-- ============================================================================
-- TEST DATA: 8 course elections (1 kada course), 8 party lists at 55 candidates bawat isa,
-- 27,016 students, vouchers at votes. Palitan ang '@turnout = 70' sa PART 2 ng 0 kung ayaw ng votes.
-- Pambura ng test data lang: 9_cleanup_remove_test_data.sql
-- ============================================================================
-- GNC-OSA load test: 8 course elections (1 per course), 7 positions each, 8 party lists each, 440 candidates total, 27016 students
-- Student login: Student ID + password 'student123'
-- Marker: election.description = 'LOADTEST...' at student email '@loadtest.invalid' (para sa cleanup)
SET NAMES utf8mb4;
SET autocommit=0;
SET unique_checks=0;
SET foreign_key_checks=0;

-- Students (27016)
SET foreign_key_checks=1;
SET unique_checks=1;

COMMIT;
SELECT (SELECT COUNT(*) FROM elections WHERE description LIKE 'LOADTEST%') elections,(SELECT COUNT(*) FROM party_lists p JOIN elections e ON e.id=p.election_id WHERE e.description LIKE 'LOADTEST%') party_lists,(SELECT COUNT(*) FROM candidates c JOIN elections e ON e.id=c.election_id WHERE e.description LIKE 'LOADTEST%') candidates,(SELECT COUNT(*) FROM students WHERE email LIKE '%@loadtest.invalid') students;

-- ==================== PART 2: VOUCHERS + VOTES ====================
-- Bawat estudyante ay bumoboto sa election ng SARILING course. Palitan ang @turnout (0 = walang votes).
SET autocommit=1;
SET @turnout = 70;

-- NOTE: gumagawa ang admin/vouchers.php ng code na 14 characters (XXXX-XXXX-XXXX) pero varchar(12) ang column
-- (natatanggal ang huling 2 characters). Nilalakihan dito para magkasya ang buong code:
ALTER TABLE voting_vouchers MODIFY code varchar(14) NOT NULL;

DROP TABLE IF EXISTS _lt_voters, _lt_pw, _lt_vp, _lt_cand, _lt_cnt;

-- weights ng party (hindi pantay) sa bawat election
CREATE TABLE _lt_pw (election_id INT, party_id INT, cum INT);
SELECT election_id, id, SUM(w) OVER (PARTITION BY election_id ORDER BY id) FROM (
  SELECT p.election_id, p.id, CASE ROW_NUMBER() OVER (PARTITION BY p.election_id ORDER BY p.id) WHEN 1 THEN 24 WHEN 2 THEN 19 WHEN 3 THEN 15 WHEN 4 THEN 12 WHEN 5 THEN 10 WHEN 6 THEN 8 WHEN 7 THEN 7 ELSE 5 END w
  FROM party_lists p JOIN elections e ON e.id=p.election_id WHERE e.description LIKE 'LOADTEST%') x;

CREATE TABLE _lt_voters (sid INT PRIMARY KEY, eid INT, r INT, party_id INT NULL, t DATETIME)
SELECT s.id sid, e.id eid, FLOOR(RAND()*100) r, NULL party_id,
       TIMESTAMPADD(SECOND, FLOOR(RAND()*9*3600), '2026-09-30 08:00:00') t
FROM students s JOIN elections e ON e.course=s.course AND e.description LIKE 'LOADTEST%'
WHERE s.email LIKE '%@loadtest.invalid' AND s.is_active=1 AND RAND()*100 < @turnout;
UPDATE _lt_voters v SET party_id = (SELECT p.party_id FROM _lt_pw p WHERE p.election_id=v.eid AND p.cum > v.r ORDER BY p.cum LIMIT 1);

SELECT eid, sid, CONCAT(UPPER(SUBSTR(MD5(CONCAT(sid,'lt')),1,4)),'-',UPPER(SUBSTR(MD5(CONCAT(sid,'lt')),5,4)),'-',UPPER(SUBSTR(MD5(CONCAT(sid,'lt')),9,4))),
       1, t, (SELECT MIN(id) FROM osa_staff WHERE role='admin')
FROM _lt_voters;

-- votes: 80% straight-ticket, 15% halo-halo, 5% abstain
CREATE TABLE _lt_cand (position_id INT, n INT, cid INT);
  FROM candidates c JOIN elections e ON e.id=c.election_id WHERE e.description LIKE 'LOADTEST%' AND c.is_approved=1;
CREATE TABLE _lt_cnt AS SELECT position_id, COUNT(*) k FROM _lt_cand GROUP BY position_id;
CREATE TABLE _lt_vp AS SELECT v.sid, v.eid, v.party_id, v.t, p.id pos, RAND() r, RAND() r2
FROM _lt_voters v JOIN positions p ON p.election_id=v.eid;

SELECT vp.eid, vp.pos, vp.sid,
  CASE WHEN vp.r < 0.05 THEN NULL
       WHEN vp.r < 0.85 AND own.id IS NOT NULL THEN own.id
       ELSE rnd.cid END,
  vp.r < 0.05, vp.t
FROM _lt_vp vp
LEFT JOIN candidates own ON own.position_id=vp.pos AND own.party_list_id=vp.party_id
LEFT JOIN _lt_cnt c ON c.position_id=vp.pos
LEFT JOIN _lt_cand rnd ON rnd.position_id=vp.pos AND rnd.n = FLOOR(vp.r2 * c.k);

DROP TABLE _lt_voters, _lt_pw, _lt_vp, _lt_cand, _lt_cnt;
SELECT (SELECT COUNT(*) FROM voting_vouchers) vouchers, (SELECT COUNT(*) FROM votes) votes;
